/**
 * Docs media (server only): the build-time manifest `content/docs/media.json` and the rules the
 * renderer, the agent Markdown and `docs:check` share about files under `public/docs-assets/`.
 *
 *   media.json: { "/docs-assets/<page>/<name>.webp": { w, h, bytes, kind, duration? } }
 *   (generated by `npm run docs:media-manifest`; kind is image | clip | video | poster)
 *
 * - Images are captured at 2x, so they display at half their pixel width (never wider than the
 *   column); a file named `…@1x.<ext>` displays at its pixel width.
 * - A dark variant sits next to its light file: `x.webp` → `x.dark.webp`, `x.mp4` → `x.dark.mp4`.
 * - A clip is referenced without an extension: `<src>.webm`, `<src>.mp4` and the poster `<src>.webp`.
 */
import fs from "node:fs";
import path from "node:path";

export interface MediaEntry {
  w?: number;
  h?: number;
  bytes?: number;
  kind?: "image" | "clip" | "video" | "poster";
  /** Seconds (clips and videos, when ffprobe was available). */
  duration?: number;
}
export type MediaManifest = Record<string, MediaEntry>;

export const PUBLIC_DIR = path.join(process.cwd(), "public");
/**
 * A site's own public folder (`<content>/public`, as the importers write it): its /docs-assets/
 * files are served from there when the app's public/ doesn't have them (siteFiles.mjs).
 */
export const SITE_PUBLIC_DIR = path.join(process.env.DOCS_CONTENT_DIR || path.join(process.cwd(), "content", "docs"), "public");
export const ASSETS_PREFIX = "/docs-assets/";

/** A root-relative /docs-assets/ path (no `..`, no query), or null. */
export function assetPath(src: unknown): string | null {
  if (typeof src !== "string" || !src.startsWith(ASSETS_PREFIX) || src.includes("..") || /[?#\s]/.test(src)) return null;
  return src;
}

/** `x.webp` → `x.dark.webp`; `x` (a clip base) → `x.dark`. */
export function darkPath(p: string): string {
  const m = /^(.*?)(\.[a-z0-9]+)?$/i.exec(p)!;
  return m[2] && /^\.(webp|png|jpe?g|gif|avif|mp4|webm)$/i.test(m[2]) ? `${m[1]}.dark${m[2]}` : `${p}.dark`;
}

export function isDarkVariant(p: string): boolean {
  return /\.dark(\.[a-z0-9]+)?$/i.test(p);
}

/** Pixel density the image was captured at. */
export function imageDensity(p: string): number {
  return /@1x\.[a-z0-9]+$/i.test(p) ? 1 : 2;
}

/** 45 → "0:45", 125.4 → "2:05". */
export function formatDuration(sec: number | undefined): string | undefined {
  if (sec === undefined || !Number.isFinite(sec) || sec <= 0) return undefined;
  const s = Math.round(sec);
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), r = s % 60;
  return h ? `${h}:${String(m).padStart(2, "0")}:${String(r).padStart(2, "0")}` : `${m}:${String(r).padStart(2, "0")}`;
}

export interface ImageVariants {
  src: string;
  dark?: string;
  w?: number;
  h?: number;
  /** CSS pixel width (pixel width / density). */
  cssW?: number;
}

export function imageVariants(manifest: MediaManifest, src: string): ImageVariants {
  const e = manifest[src];
  const d = darkPath(src);
  const w = e?.w, h = e?.h;
  return { src, dark: manifest[d] ? d : undefined, w, h, cssW: w ? Math.round(w / imageDensity(src)) : undefined };
}

export interface ClipSource {
  webm?: string;
  mp4?: string;
  poster?: string;
}
export interface ClipVariants {
  light: ClipSource;
  dark?: ClipSource;
  w?: number;
  h?: number;
  duration?: number;
}

function clipSource(manifest: MediaManifest, base: string, known: boolean): ClipSource {
  const has = (p: string) => (known ? !!manifest[p] : true);
  return {
    webm: has(`${base}.webm`) ? `${base}.webm` : undefined,
    mp4: has(`${base}.mp4`) ? `${base}.mp4` : undefined,
    poster: has(`${base}.webp`) ? `${base}.webp` : undefined,
  };
}

/**
 * The files of a clip. While the manifest knows none of them (assets being captured), every file
 * is assumed so the page still renders; `docs:check` reports the gap.
 */
export function clipVariants(manifest: MediaManifest, src: string, theme: "light" | "both" = "light"): ClipVariants {
  const known = [".webm", ".mp4", ".webp"].some((x) => manifest[src + x]);
  const light = clipSource(manifest, src, known);
  const d = darkPath(src);
  const darkKnown = [".webm", ".mp4", ".webp"].some((x) => manifest[d + x]);
  const dark = theme === "both" && (darkKnown || !known) ? clipSource(manifest, d, darkKnown) : undefined;
  const main = manifest[`${src}.mp4`] ?? manifest[`${src}.webm`] ?? manifest[`${src}.webp`];
  return { light, dark, w: main?.w, h: main?.h, duration: (manifest[`${src}.mp4`] ?? manifest[`${src}.webm`])?.duration };
}

export interface Cue {
  start: number;
  text: string;
}

/** WebVTT timestamp → seconds (`01:02.500`, `1:01:02.500`). */
function vttTime(t: string): number {
  const parts = t.trim().split(":").map(Number);
  return parts.reduce((acc, n) => acc * 60 + n, 0);
}

/** The cues of a WebVTT file under public/ (chapters), or [] when it is missing or malformed. */
export function readVttCues(publicPath: string | undefined): Cue[] {
  const p = assetPath(publicPath);
  if (!p) return [];
  let src = "";
  for (const dir of [PUBLIC_DIR, SITE_PUBLIC_DIR]) {
    try {
      src = fs.readFileSync(path.join(dir, p), "utf8");
      break;
    } catch {
      /* the next folder */
    }
  }
  if (!/^﻿?WEBVTT/.test(src)) return [];
  const out: Cue[] = [];
  for (const block of src.replace(/\r\n?/g, "\n").split(/\n{2,}/)) {
    const lines = block.split("\n");
    const at = lines.findIndex((l) => l.includes("-->"));
    if (at < 0) continue;
    const start = vttTime(lines[at].split("-->")[0]);
    const text = lines.slice(at + 1).join(" ").replace(/<[^>]+>/g, "").trim();
    if (Number.isFinite(start) && text) out.push({ start, text });
  }
  return out;
}
